"""Evidence-based request evaluation."""

import json


def _canonical(value):
    """Return the canonical JSON representation used for exact comparisons."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def _superseded_sources(record):
    supersedes = record.get("supersedes", [])
    if isinstance(supersedes, list):
        return supersedes
    if supersedes is None:
        return []
    return [supersedes]


def evaluate(request, evidence, policy):
    """Evaluate one request against evidence under the supplied policy."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue
        conditions = record.get("conditions", {})
        if any(
            name not in conditions
            or _canonical(conditions[name]) != _canonical(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = {
        source
        for record in eligible
        for source in _superseded_sources(record)
    }
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record.get("source") for record in eligible)
    canonical_values = {_canonical(record.get("value")) for record in eligible}
    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = eligible[0].get("value")
    return {
        "status": "unsupported" if value is False else "supported",
        "value": value,
        "sources": sources,
        "unknowns": [],
    }
